  {
    id: 'grid',
    label: 'Data Grid',
    editable: true,
    children: [
      { id: 'grid-community', label: '@mui/x-data-grid', editable: true },
      { id: 'grid-pro', label: '@mui/x-data-grid-pro', editable: true },
      { id: 'grid-premium', label: '@mui/x-data-grid-premium', editable: true },
